function EmailField({ value, onChange, submitted }: FieldProps) {
  const [touched, setTouched] = useState(false)
  const error = validateEmail(value) // '' when valid
  const showError = error && (touched || submitted)
  const errorId = 'email-error'

  return (
    <div className="field" data-state={showError ? 'error' : value ? 'success' : 'idle'}>
      <label htmlFor="email">Work email</label>
      <input
        id="email"
        type="email"
        value={value}
        aria-invalid={!!showError}
        aria-describedby={showError ? errorId : undefined}
        onBlur={() => setTouched(true)}
        onChange={(e) => onChange(e.target.value)} // re-validates live
      />
      {showError && (
        <p id={errorId} role="alert" className="error">
          {error} {/* e.g. "Add the @ — try name@company.com" */}
        </p>
      )}
    </div>
  )
}

