:root {
  --text-primary-cta: clamp(1.05rem, 1rem + 0.4vw, 1.25rem);
  --weight-primary: 650;
  --weight-secondary: 450;
  --color-accent: oklch(62% 0.19 264);
  --color-muted: oklch(55% 0.01 264);
}
.checkout-actions { display: flex; flex-direction: column; gap: 0.75rem; }
.checkout-actions .primary {
  order: -1;
  font-size: var(--text-primary-cta);
  font-weight: var(--weight-primary);
  background: var(--color-accent);
}
.checkout-actions .secondary {
  font-weight: var(--weight-secondary);
  color: var(--color-muted);
  background: none;
}
.checkout-actions .legal { font-size: 0.8125rem; color: var(--color-muted); }

