// TIER 1 — PRIMITIVES: name the VALUE, never used directly by components
export const primitive = {
  gray900: 'oklch(20% 0 0)', gray500: 'oklch(55% 0 0)', gray300: 'oklch(85% 0 0)',
  red600:  'oklch(52% 0.20 27)',   // AA on white for text
  blue600: 'oklch(55% 0.19 255)',
  space2: '0.5rem', space4: '1rem',
  radiusMd: '0.5rem',
}

// TIER 2 — SEMANTICS: name the DECISION; components consume ONLY these
export const token = {
  colorTextDefault:  primitive.gray900,
  colorTextError:    primitive.red600,   // "this is what error MEANS"
  colorActionDisabled: primitive.gray300,// disabled != error, on purpose
  focusRing:         primitive.blue600,  // keyboard users see this
  spaceFormGap:      primitive.space4,
  radiusControl:     primitive.radiusMd,
}

// COMPONENT — reads intent, not values. Swap a primitive → this moves too.
export const errorTextStyle = {
  color: token.colorTextError,
  marginTop: token.spaceFormGap,
}
export const disabledPayStyle = {
  color: token.colorActionDisabled,
  outline: `2px solid ${token.focusRing}`, // still focusable when disabled-ish
}

